begin;
set local search_path = public, extensions;
select no_plan();
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.tenants'::regclass,'public.units'::regclass,'public.profiles'::regclass,'public.tenant_memberships'::regclass,'public.membership_units'::regclass,'public.tenant_invitations'::regclass,'public.tenant_entitlements'::regclass,'public.audit_logs'::regclass)), 'RLS em todas as tabelas públicas');
select ok(not has_table_privilege('authenticated','private.platform_memberships','SELECT'), 'Autoridade global inacessível');
select ok(not has_table_privilege('anon','public.tenants','SELECT'), 'Anon sem dados');
select ok(not has_function_privilege('anon','public.invite_member(uuid,uuid,text,text)','EXECUTE'), 'Anon sem RPC');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not coalesce(p.proconfig @> array['search_path=""'],false)), 'Definers com search_path vazio');
select is((select public from storage.buckets where id='foundation-test'),false,'Bucket privado');
select throws_ok($$insert into public.membership_units values('10000000-0000-0000-0000-000000000001',(select id from public.tenant_memberships where tenant_id='10000000-0000-0000-0000-000000000001' limit 1),'20000000-0000-0000-0000-000000000011')$$,'23503',null,'FK composta impede unidade de B no vínculo A');
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select is((select count(*)::int from public.tenants),1,'A SELECT somente tenant A');
select is((select count(*)::int from public.units),1,'A somente unidade atribuída');
select is((select count(*)::int from public.units where id='10000000-0000-0000-0000-000000000012'),0,'Unidade não atribuída invisível');
select ok(public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','members.manage'),'A admin no escopo');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011','unit.read'),'RPC bloqueia unidade de outro tenant');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001',null,'unit.read','agenda'),'Módulo não habilitado negado');
select lives_ok($$update public.units set name='Teste A' where id='10000000-0000-0000-0000-000000000011'$$,'A UPDATE permitido na coluna nome');
with changed as (update public.units set name='ataque' where tenant_id='20000000-0000-0000-0000-000000000001' returning id) select is((select count(*)::int from changed),0,'UPDATE B não alcança linha');
select throws_ok($$update public.units set tenant_id='20000000-0000-0000-0000-000000000001'$$,'42501',null,'Coluna tenant imutável');
select throws_ok($$update public.tenant_memberships set role='clinic_admin'$$,'42501',null,'Escalada de papel negada');
select throws_ok($$update public.tenant_memberships set status='active'$$,'42501',null,'Reativação direta negada');
select throws_ok($$update public.tenants set status='active'$$,'42501',null,'Estado plataforma protegido');
select throws_ok($$insert into public.tenants(slug,name) values('ataque','Ataque')$$,'42501',null,'INSERT tenant negado');
select throws_ok($$delete from public.tenant_memberships$$,'42501',null,'DELETE vínculo direto negado');
select throws_ok($$update public.tenant_entitlements set enabled=true$$,'42501',null,'Entitlement protegido');
select throws_ok($$insert into public.audit_logs(action,entity,entity_id) values('forjado','x','x')$$,'42501',null,'Auditoria não forjável');
select throws_ok($$select * from private.platform_memberships$$,'42501',null,'Leitura autoridade privada negada');
select throws_ok($$select * from public.platform_tenants()$$,'42501',null,'Admin clínica não é admin Zetta');
select lives_ok($$update public.profiles set display_name='Usuário A' where id=auth.uid()$$,'Perfil próprio editável');
select is((select count(*)::int from public.profiles),1,'Perfil de B privado');
select throws_ok($$select public.invite_member('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011','x@example.com','clinic_admin')$$,'42501',null,'Convite B negado');
select throws_ok($$select public.invite_member('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000012','x@example.com','clinic_admin')$$,'42501',null,'Convite unidade não atribuída negado');
select lives_ok($$insert into storage.objects(bucket_id,name) values('foundation-test','10000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000011/a.txt')$$,'A upload autorizado');
select is((select count(*)::int from storage.objects),1,'A SELECT/download objeto próprio');
select throws_ok($$insert into storage.objects(bucket_id,name) values('foundation-test','20000000-0000-0000-0000-000000000001/20000000-0000-0000-0000-000000000011/ataque.txt')$$,'42501',null,'A upload B negado');
select throws_ok($$insert into storage.objects(bucket_id,name) values('foundation-test','10000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000012/ataque.txt')$$,'42501',null,'A upload unidade não atribuída negado');
select throws_ok($$update storage.objects set name='20000000-0000-0000-0000-000000000001/20000000-0000-0000-0000-000000000011/roubo.txt'$$,'42501',null,'WITH CHECK impede mover objeto para B');
select lives_ok($$update storage.objects set metadata='{"test":true}' where name like '%/a.txt'$$,'A UPDATE objeto próprio');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='b@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select is((select count(*)::int from public.tenants),1,'B SELECT somente B');
select is((select count(*)::int from storage.objects),0,'B download A bloqueado');
with changed as (delete from storage.objects returning id) select is((select count(*)::int from changed),0,'B DELETE A não alcança linha');
with changed as (update storage.objects set metadata='{}' returning id) select is((select count(*)::int from changed),0,'B UPDATE A não alcança linha');
select lives_ok($$insert into storage.objects(bucket_id,name) values('foundation-test','20000000-0000-0000-0000-000000000001/20000000-0000-0000-0000-000000000011/b.txt')$$,'B upload próprio');
select is((select count(*)::int from storage.objects),1,'B download próprio');
select lives_ok($$update storage.objects set metadata='{}'$$,'B UPDATE próprio');
with changed as (delete from storage.objects returning id) select is((select count(*)::int from changed),1,'B DELETE próprio');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='multi@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select is((select count(*)::int from public.tenants),2,'Multi vê dois vínculos');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001',null,'members.manage'),'Manager não administra vínculos');
reset role;
update public.tenant_memberships set status='revoked' where user_id=(select id from auth.users where email='multi@example.com') and tenant_id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.tenants),1,'Revogação A remove acesso sem trocar JWT');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','storage.read'),'Revogação bloqueia RPC');
select is((select count(*)::int from storage.objects),0,'Revogação bloqueia download A');
select throws_ok($$insert into storage.objects(bucket_id,name) values('foundation-test','10000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000011/revogado.txt')$$,'42501',null,'Revogação bloqueia upload');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='revogado@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select is((select count(*)::int from public.tenants),0,'Revogado SELECT vazio');
with changed as (update public.units set name='ataque' returning id) select is((select count(*)::int from changed),0,'Revogado UPDATE vazio');
select throws_ok($$select public.invite_member('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','x@example.com','manager')$$,'42501',null,'Revogado RPC negado');
with changed as (delete from storage.objects returning id) select is((select count(*)::int from changed),0,'Revogado DELETE vazio');
reset role;
-- Admin global não ganha vínculo operacional automaticamente.
insert into private.platform_memberships(user_id,role) select id,'superadmin' from auth.users where email='revogado@example.com';
set local role authenticated;
select is(public.platform_context(),'superadmin','Papel global independente');
select is((select count(*)::int from public.platform_tenants()),2,'Superadmin somente metadados pelo RPC');
select is((select count(*)::int from public.tenants),0,'Superadmin sem bypass operacional');
reset role;
select ok(exists(select 1 from public.audit_logs where entity='tenant_memberships' and action='UPDATE'),'Revogação auditada na transação');
-- Módulo e estado vigentes devem bloquear o mesmo JWT.
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
update public.tenant_entitlements set enabled=false where tenant_id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.tenants),0,'Core desabilitado bloqueia SELECT');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','storage.write'),'Core desabilitado bloqueia escrita');
reset role;
update public.tenant_entitlements set enabled=true,valid_until=now()-interval '1 second',valid_from=now()-interval '1 day' where tenant_id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.tenants),0,'Entitlement expirado bloqueia acesso');
reset role;
update public.tenant_entitlements set valid_until=null where tenant_id='10000000-0000-0000-0000-000000000001';
update public.tenants set status='suspended' where id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.tenants),0,'Tenant suspenso bloqueia SELECT');
select throws_ok($$select public.invite_member('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','x@example.com','manager')$$,'42501',null,'Tenant suspenso bloqueia RPC');
reset role;
update public.tenants set status='active' where id='10000000-0000-0000-0000-000000000001';
update public.units set active=false where id='10000000-0000-0000-0000-000000000011';
set local role authenticated;
select is((select count(*)::int from public.units),0,'Unidade inativa bloqueia SELECT');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','storage.read'),'Unidade inativa bloqueia download');
reset role;
update public.units set active=true where id='10000000-0000-0000-0000-000000000011';
set local role authenticated;
with deleted as (delete from storage.objects returning id) select is((select count(*)::int from deleted),1,'A DELETE do próprio objeto');
reset role;
-- Equipe e auditoria de unidade restrita não podem vazar ao admin do Centro.
insert into public.tenant_memberships(id,tenant_id,user_id,role) values('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',(select id from auth.users where email='b@example.com'),'manager');
insert into public.membership_units values('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000012');
update public.units set name='Unidade restrita teste' where id='10000000-0000-0000-0000-000000000012';
set local role authenticated;
select is((select count(*)::int from public.tenant_memberships where id='30000000-0000-0000-0000-000000000001'),0,'Admin não lê equipe fora do escopo');
select throws_ok($$select public.revoke_membership('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001')$$,'42501',null,'Admin não revoga equipe fora do escopo');
select is((select count(*)::int from public.audit_logs where unit_id='10000000-0000-0000-0000-000000000012'),0,'Admin não lê eventos de unidade restrita');
reset role;
-- Bootstrap da plataforma com e-mail sintético, sem cadastrar o e-mail real autorizado.
insert into private.platform_admin_emails values('platform-bootstrap@example.com');
update auth.users set raw_user_meta_data='{"role":"superadmin"}' where email='a@example.com';
set local role authenticated;
select is(public.platform_context(),null::text,'Metadados Auth não concedem papel global');
reset role;
update auth.users set email='platform-bootstrap@example.com',email_confirmed_at=null where email='a@example.com';
set local role authenticated;
select is(public.platform_context(),null::text,'E-mail não confirmado não recebe bootstrap');
reset role;
update auth.users set email_confirmed_at=now() where email='platform-bootstrap@example.com';
set local role authenticated;
select is(public.platform_context(),'superadmin','Whitelist privada e confirmação concedem bootstrap');
select is((select count(*)::int from public.tenants),1,'Bootstrap não amplia clínicas acessíveis');
reset role;
select * from finish();
rollback;
